    .replace(/\r\n|[\r\n]/g, '<br>');
}

/** Title markup: inline formatting only — a heading stays on one line. */
export function renderTitle(source: string): string {
  return renderInline(source)
    .replace(BR_TAG, ' ')
    .replace(/\r\n|[\r\n]/g, ' ');
}

/** The visible text of a note field, used for search matching. */
export function toPlainText(source: string): string {
  return source
    .replace(/<\s*br\s*\/?\s*>/gi, ' ')
    .replace(/<\/?(?:b|strong|i|em|a)(?:\s[^>]*)?>/gi, '')
    .replace(/\s+/g, ' ')
    .trim();
}

