:root {
  --bg: #f6f5f2;
  --surface: #ffffff;
  --ink: #1c1917;
  --muted: #57534e;
  --line: #ddd8d0;
  --accent: #0f766e;
  --accent-soft: #ccfbf1;
  --danger: #b91c1c;
  color-scheme: light dark;
}

@media (prefers-color-scheme: dark) {
  :root {
    --bg: #12100e;
    --surface: #1c1917;
    --ink: #f5f5f4;
    --muted: #a8a29e;
    --line: #3a3531;
    --accent: #5eead4;
    --accent-soft: #134e4a;
    --danger: #fca5a5;
  }
}

* {
  box-sizing: border-box;
}

body {
  margin: 0;
  background: var(--bg);
  color: var(--ink);
  font: 16px/1.55 system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
}

#app {
  max-width: 46rem;
  margin: 0 auto;
  padding: 1.5rem 1rem 4rem;
  display: grid;
  gap: 1.25rem;
}

.page-head h1 {
  margin: 0;
  font-size: 1.9rem;
  letter-spacing: -0.02em;
}

.tagline {
  margin: 0.25rem 0 0;
  color: var(--muted);
}

.card {
  background: var(--surface);
  border: 1px solid var(--line);
  border-radius: 12px;
  padding: 1rem 1.1rem 1.1rem;
}

.card h2 {
  margin: 0 0 0.75rem;
  font-size: 1.05rem;
  text-transform: uppercase;
  letter-spacing: 0.06em;
  color: var(--muted);
}

.field {
  margin: 0 0 0.85rem;
  display: grid;
  gap: 0.3rem;
}

label {
  font-weight: 600;
  font-size: 0.9rem;
}

.optional {
  font-weight: 400;
  color: var(--muted);
}

input,
textarea {
  font: inherit;
  color: inherit;
  background: var(--bg);
  border: 1px solid var(--line);
  border-radius: 8px;
  padding: 0.5rem 0.6rem;
  width: 100%;
}

textarea {
  resize: vertical;
  min-height: 5.5rem;
}

input:focus-visible,
textarea:focus-visible,
button:focus-visible {
  outline: 3px solid var(--accent);
  outline-offset: 2px;
}

.help {
  font-size: 0.82rem;
  color: var(--muted);
}

.help code {
  background: var(--bg);
  border: 1px solid var(--line);
  border-radius: 4px;
  padding: 0 0.25em;
  font-size: 0.95em;
}

.actions {
  margin: 0;
}

button[type='submit'] {
  font: inherit;
  font-weight: 600;
  color: var(--bg);
  background: var(--accent);
  border: 1px solid transparent;
  border-radius: 8px;
  padding: 0.5rem 1.1rem;
  cursor: pointer;
}

button[type='submit']:hover {
  filter: brightness(1.08);
}

.error {
  margin: 0.6rem 0 0;
  color: var(--danger);
  font-size: 0.9rem;
  min-height: 1.2em;
}

.error:empty {
  margin: 0;
  min-height: 0;
}

#results-line {
  margin: 0;
  color: var(--muted);
  min-height: 1.4em;
}

#feed {
  display: grid;
  gap: 0.9rem;
}

.note {
  background: var(--surface);
  border: 1px solid var(--line);
  border-left: 4px solid transparent;
  border-radius: 12px;
  padding: 0.9rem 1.1rem 1rem;
}

.note[aria-current='true'] {
  border-left-color: var(--accent);
  background: color-mix(in srgb, var(--accent-soft) 45%, var(--surface));
}

.note-head {
  display: flex;
  align-items: center;
  gap: 0.7rem;
}

.note-avatar {
  width: 40px;
  height: 40px;
  border-radius: 50%;
  object-fit: cover;
  background: var(--bg);
  flex: none;
}

.note-heading {
  margin: 0;
  font-size: 1.15rem;
  min-width: 0;
}

.note-title {
  font: inherit;
  color: inherit;
  background: none;
  border: 0;
  border-radius: 6px;
  padding: 0.1rem 0.2rem;
  margin-left: -0.2rem;
  text-align: left;
  cursor: pointer;
}

.note-title:hover {
  color: var(--accent);
  text-decoration: underline;
}

.note-body {
  margin: 0.5rem 0 0;
  overflow-wrap: anywhere;
}

.note-body a {
  color: var(--accent);
}

.note-date {
  display: block;
  margin-top: 0.6rem;
  font-size: 0.8rem;
  color: var(--muted);
}

.empty {
  margin: 0;
  padding: 1.2rem;
  text-align: center;
  color: var(--muted);
  border: 1px dashed var(--line);
  border-radius: 12px;
}

