import { spawn, spawnSync } from 'node:child_process';
import path from 'node:path';
import { chromium } from '@playwright/test';

const dir = '/workspace/benchmark/runs/lanes/lane-1/arm-a-vibe';
spawnSync('pnpm', ['build'], { cwd: dir, stdio: 'ignore' });
const port = 4811;
const server = spawn('node', [path.join(dir, 'server.mjs'), '--port', String(port)], { cwd: dir, stdio: 'ignore' });
await new Promise((r) => setTimeout(r, 600));
const base = `http://127.0.0.1:${port}/`;

let pass = 0;
const fails = [];
function check(name, cond, extra = '') {
  if (cond) pass++;
  else fails.push(`${name}${extra ? ' :: ' + extra : ''}`);
}

const browser = await chromium.launch();
const ctx = await browser.newContext();
const page = await ctx.newPage();
const errors = [];
const dialogs = [];
page.on('pageerror', (e) => errors.push(String(e.message ?? e)));
page.on('console', (m) => m.type() === 'error' && errors.push(m.text()));
page.on('dialog', async (d) => { dialogs.push(d.message()); await d.dismiss(); });

try {
  // --- seed + ordering -----------------------------------------------------
  await page.goto(base, { waitUntil: 'load' });
  const ids = await page.$$eval('#feed article.note', (ns) => ns.map((n) => n.dataset.noteId));
  check('seeds 6 notes newest-first', JSON.stringify(ids) === JSON.stringify(['6','5','4','3','2','1']), ids.join(','));

  // --- rich text -----------------------------------------------------------
  const n1 = await page.$eval('.note[data-note-id="1"] .note-body', (e) => e.innerHTML);
  check('bold renders as <b>', /<b>OWASP AppSec Days Porto<\/b>/.test(n1), n1);
  check('<br> renders', /<br>/.test(n1), n1);
  const boldWeight = await page.$eval('.note[data-note-id="1"] .note-body b', (e) => getComputedStyle(e).fontWeight);
  check('bold word displays bold', Number(boldWeight) >= 700, boldWeight);
  const link = await page.$eval('.note[data-note-id="4"] .note-body a', (a) => a.getAttribute('href'));
  check('link is clickable anchor', link === 'https://www.livrarialello.pt/', String(link));
  const ital = await page.$eval('.note[data-note-id="2"] .note-body i', (e) => getComputedStyle(e).fontStyle);
  check('italic displays italic', ital === 'italic', ital);

  // --- avatars -------------------------------------------------------------
  const avatarIds = await page.$$eval('#feed .note', (ns) =>
    ns.filter((n) => n.querySelector('img.note-avatar')).map((n) => n.dataset.noteId));
  check('avatars only where given', JSON.stringify(avatarIds.sort()) === JSON.stringify(['1','3','6']), avatarIds.join(','));

  // --- search --------------------------------------------------------------
  await page.fill('#search', 'douro');
  await page.waitForTimeout(120);
  const shown = await page.$$eval('#feed article.note', (ns) => ns.map((n) => n.dataset.noteId));
  check('search filters feed', JSON.stringify(shown) === JSON.stringify(['5','2']), shown.join(','));
  check('results-line text', (await page.textContent('#results-line')) === 'results for "douro"', await page.textContent('#results-line'));
  check('hash carries query', page.url().endsWith('#q=douro'), page.url());

  // case-insensitive
  await page.fill('#search', 'DOURO');
  await page.waitForTimeout(80);
  check('search is case-insensitive', (await page.$$('#feed article.note')).length === 2);
  await page.fill('#search', 'douro');
  await page.waitForTimeout(80);

  // --- selection -----------------------------------------------------------
  await page.click('.note[data-note-id="5"] .note-title');
  await page.waitForTimeout(80);
  check('selected gets aria-current', (await page.getAttribute('.note[data-note-id="5"]', 'aria-current')) === 'true');
  check('only one selected', (await page.$$('[aria-current="true"]')).length === 1);
  check('hash q+note', page.url().endsWith('#q=douro&note=5'), page.url());

  await page.fill('#search', '');
  await page.waitForTimeout(80);
  check('results-line empty with no query', (await page.textContent('#results-line')) === '');
  check('hash note only', page.url().endsWith('#note=5'), page.url());

  // --- deep link restore ---------------------------------------------------
  await page.goto(base + '#q=port&note=1', { waitUntil: 'load' });
  await page.waitForTimeout(150);
  check('restores query', (await page.inputValue('#search')) === 'port');
  check('restores results-line', (await page.textContent('#results-line')) === 'results for "port"');
  check('restores selection', (await page.getAttribute('.note[data-note-id="1"]', 'aria-current')) === 'true');
  check('restores filter', (await page.$$('#feed article.note')).length === 1);

  // reversed order + spaces in query
  await page.goto(base + '#note=6&q=keynote%20room', { waitUntil: 'load' });
  await page.waitForTimeout(150);
  check('parses either order', (await page.inputValue('#search')) === 'keynote room'
    && (await page.getAttribute('.note[data-note-id="6"]', 'aria-current')) === 'true');

  // --- add a note ----------------------------------------------------------
  await page.goto(base, { waitUntil: 'load' });
  await page.fill('#title', 'Ponte Luis I');
  await page.fill('#body', 'Cross the <b>top deck</b> at dusk.\nMind the metro.');
  await page.fill('#avatar', 'https://example.com/a.png');
  await page.click('#note-form button[type=submit]');
  await page.waitForTimeout(120);
  const first = await page.$eval('#feed article.note', (n) => n.dataset.noteId);
  check('new note is id 7, newest-first', first === '7', first);
  check('form cleared', (await page.inputValue('#title')) === '' && (await page.inputValue('#body')) === ''
    && (await page.inputValue('#avatar')) === '');
  const newBody = await page.$eval('.note[data-note-id="7"] .note-body', (e) => e.innerHTML);
  check('typed bold + newline render', /<b>top deck<\/b>/.test(newBody) && /Mind/.test(newBody) && /<br>/.test(newBody), newBody);
  check('new note avatar', (await page.getAttribute('.note[data-note-id="7"] img.note-avatar', 'src')) === 'https://example.com/a.png');

  await page.reload({ waitUntil: 'load' });
  await page.waitForTimeout(150);
  check('persists across reload', (await page.$$('#feed article.note')).length === 7
    && (await page.textContent('.note[data-note-id="7"] .note-title')).includes('Ponte Luis I'));

  // --- injection probes ----------------------------------------------------
  const probes = [
    ['<script>window.__x=1</script>hi', '', 'script tag'],
    ['<img src=x onerror="window.__x=1">', '', 'img onerror'],
    ['<b onclick="window.__x=1">bold</b>', '', 'event handler on allowed tag'],
    ['<a href="javascript:window.__x=1">click</a>', '', 'javascript: href'],
    ['<a href="JaVaScRiPt&colon;window.__x=1">click</a>', '', 'entity-smuggled scheme'],
    ['<a href="java\tscript:window.__x=1">click</a>', '', 'tab-split scheme'],
    ['<svg onload="window.__x=1"></svg>', '', 'svg onload'],
    ['"><img src=x onerror="window.__x=1">', '', 'attribute break-out'],
    ['<b>ok</b>', 'javascript:window.__x=1', 'javascript: avatar'],
    ['<b>ok</b>', '" onerror="window.__x=1', 'avatar attribute break-out'],
    ['<iframe src="javascript:window.__x=1"></iframe>', '', 'iframe'],
  ];
  for (const [body, avatar, label] of probes) {
    await page.fill('#title', `probe ${label}`);
    await page.fill('#body', body);
    await page.fill('#avatar', avatar);
    await page.click('#note-form button[type=submit]');
    await page.waitForTimeout(60);
  }
  await page.reload({ waitUntil: 'load' });
  await page.waitForTimeout(300);

  check('no script executed', (await page.evaluate(() => window.__x)) === undefined, String(await page.evaluate(() => window.__x)));
  check('no dialogs', dialogs.length === 0, dialogs.join('|'));
  const feedHtml = await page.$eval('#feed', (e) => e.innerHTML);
  check('no injected script/iframe/svg elements', (await page.$$('#feed script, #feed iframe, #feed svg, #feed img:not(.note-avatar)')).length === 0);
  check('no event-handler attributes', !/\son(error|click|load|mouseover)\s*=/i.test(feedHtml),
    (feedHtml.match(/\son\w+\s*=[^\s>]*/i) ?? [''])[0]);
  const hrefs = await page.$$eval('#feed a', (as) => as.map((a) => a.href));
  check('no javascript: hrefs', !hrefs.some((h) => h.toLowerCase().startsWith('javascript:')), hrefs.join('|'));
  const srcs = await page.$$eval('#feed img', (is) => is.map((i) => i.getAttribute('src') ?? ''));
  check('no javascript: img srcs', !srcs.some((s) => s.toLowerCase().replace(/\s/g, '').startsWith('javascript:')), srcs.join('|'));
  check('probe text still visible', (await page.textContent('#feed')).includes('window.__x=1'));

  check('no console/page errors', errors.length === 0, errors.join(' | '));
} finally {
  await browser.close();
  server.kill();
}

console.log(`\npassed ${pass}/${pass + fails.length}`);
if (fails.length) { console.log('FAILURES:'); for (const f of fails) console.log('  ✗ ' + f); }
process.exit(fails.length ? 1 : 0);

